  console.log(source_default.dim("┌─────────────────────────────────────────┐"));
  console.log(`${source_default.dim("│")} ${source_default.bold("Provider")}  ${source_default.green(provider.padEnd(30))} ${source_default.dim("│")}`);
  console.log(`${source_default.dim("│")} ${source_default.bold("Model    ")}  ${source_default.green(model.slice(0, 30).padEnd(30))} ${source_default.dim("│")}`);
  console.log(`${source_default.dim("│")} ${source_default.bold("OS       ")}  ${source_default.dim(platform2.slice(0, 30).padEnd(30))} ${source_default.dim("│")}`);
  console.log(`${source_default.dim("│")} ${source_default.bold("CWD      ")}  ${source_default.dim(cwd.slice(-30).padEnd(30))} ${source_default.dim("│")}`);
  console.log(`${source_default.dim("│")} ${source_default.bold("Memories ")}  ${source_default.magenta(String(memCount).padEnd(30))} ${source_default.dim("│")}`);
  console.log(`${source_default.dim("│")} ${source_default.bold("Skills   ")}  ${source_default.cyan((activeSkills.join(", ") || "none").slice(0, 30).padEnd(30))} ${source_default.dim("│")}`);
  console.log(source_default.dim("└─────────────────────────────────────────┘"));
