import { existsSync as existsSync2, readFileSync as readFileSync3 } from "node:fs";
import { resolve as resolve3 } from "node:path";
function loadEnvFile2(filePath) {
  if (!existsSync2(filePath))
    return;
  const content = readFileSync3(filePath, "utf8");
  const lines = content.split(/\r?\n/);
  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (!line || line.startsWith("#"))
      continue;
    const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/);
    if (!match)
      continue;
    const [, key, rawValue = ""] = match;
    if (!key)
      continue;
    let value = rawValue;
    if (value.startsWith('"') && value.endsWith('"') || value.startsWith("'") && value.endsWith("'")) {
      value = value.slice(1, -1);
    }
    if (process.env[key] === undefined)
      process.env[key] = value;
  }
}
function loadEnv() {
  const cwdEnvPath = resolve3(process.cwd(), ".env");
  const projectEnvPath = resolve3(import.meta.dir, ".env");
  const globalEnvPath = getEnvPath();
  loadEnvFile2(globalEnvPath);
  if (cwdEnvPath !== globalEnvPath)
    loadEnvFile2(cwdEnvPath);
  if (projectEnvPath !== cwdEnvPath && projectEnvPath !== globalEnvPath)
    loadEnvFile2(projectEnvPath);
}
loadEnv();
