program2.command("doctor").description("Check config, test AI connection, verify tools, show status.").action(async () => {
  const { existsSync: existsSync3 } = await import("node:fs");
  const { join: join2 } = await import("node:path");
  const { homedir: homedir2 } = await import("node:os");
  console.log(source_default.bold.cyan(`
\uD83E\uDE7A Olly Doctor
`));
  const ollyDir = join2(homedir2(), ".olly");
  const envFile = join2(ollyDir, ".env");
  const checks3 = [];
  checks3.push({ name: "Config dir (~/.olly/)", ok: existsSync3(ollyDir) });
  checks3.push({ name: "Config file (~/.olly/.env)", ok: existsSync3(envFile) });
  const provider = process.env.OLLY_PROVIDER ?? "(not set)";
  const model = process.env.OLLY_MODEL ?? "(not set)";
  checks3.push({ name: `Provider: ${provider}`, ok: provider !== "(not set)", info: `Model: ${model}` });
  const apiKeyMap = {
    openai: "OPENAI_API_KEY",
    anthropic: "ANTHROPIC_API_KEY",
    google: "GOOGLE_GENERATIVE_AI_API_KEY",
    groq: "GROQ_API_KEY",
    openrouter: "OPENROUTER_API_KEY"
  };
  const keyEnv = apiKeyMap[provider.toLowerCase()];
  if (keyEnv) {
    const hasKey = !!process.env[keyEnv];
    checks3.push({ name: `API Key (${keyEnv})`, ok: hasKey, info: hasKey ? "Set ✓" : "Missing!" });
  }
  const memDir = join2(ollyDir, "memory");
  const memCount = existsSync3(memDir) ? (await import("node:fs")).readdirSync(memDir).filter((f2) => f2.endsWith(".md")).length : 0;
  checks3.push({ name: "Memory system", ok: true, info: `${memCount} memories` });
  const { listSkills: listSkills2 } = await Promise.resolve().then(() => (init_skills(), exports_skills));
  const skills = listSkills2();
  const enabledCount = skills.filter((s) => s.enabled).length;
  checks3.push({ name: "Skills", ok: true, info: `${enabledCount}/${skills.length} enabled` });
  process.stdout.write(source_default.dim("Testing AI connection... "));
  try {
    const { getAgentModel: getAgentModel2 } = await Promise.resolve().then(() => (init_ai(), exports_ai));
    const { generateText: generateText2 } = await Promise.resolve().then(() => (init_dist9(), exports_dist));
    await generateText2({ model: getAgentModel2(), prompt: "Reply with just: ok", maxOutputTokens: 5 });
    process.stdout.write(source_default.green(`✔ Connected
`));
    checks3.push({ name: "AI connection", ok: true });
  } catch (err) {
    const msg = err instanceof Error ? err.message.slice(0, 60) : String(err);
    process.stdout.write(source_default.red(`✖ Failed: ${msg}
`));
    checks3.push({ name: "AI connection", ok: false, info: msg });
  }
  console.log();
  for (const c of checks3) {
    const icon = c.ok ? source_default.green("✔") : source_default.red("✖");
    const info = c.info ? source_default.dim(` (${c.info})`) : "";
    console.log(`  ${icon} ${c.name}${info}`);
  }
  const allOk = checks3.every((c) => c.ok);
  console.log();
  if (allOk) {
    console.log(source_default.green.bold("  All checks passed! Olly is ready."));
  } else {
    console.log(source_default.yellow("  Some checks failed. Run 'olly setup' to fix configuration."));
  }
  console.log();
});
